insert into problems (slug, title, difficulty, category, description) values
    ('two-sum', 'Two Sum', 'Easy', 'Array', 'Given an array of integers and a target, return the indices of two distinct values whose sum equals the target. Assume exactly one valid answer exists; the array contains 2 to 10,000 elements and values may be negative.'),
    ('add-two-numbers', 'Add Two Numbers', 'Medium', 'Linked List', 'Add two non-negative integers represented by linked lists whose digits are stored in reverse order, then return the sum in the same format. Each list has 1 to 100 nodes, each node stores a digit from 0 to 9, and there are no leading zeroes except for zero itself.'),
    ('longest-substring-without-repeating-characters', 'Longest Substring Without Repeating Characters', 'Medium', 'String', 'Find the length of the longest contiguous substring that contains no repeated characters. The input string may contain letters, digits, symbols, and spaces, and its length is between 0 and 50,000 characters.'),
    ('valid-parentheses', 'Valid Parentheses', 'Easy', 'Stack', 'Determine whether a string of brackets is valid: every opening bracket must be closed by the same type in the correct order. The string contains only (), {}, and [] characters and has a length between 1 and 10,000.'),
    ('merge-two-sorted-lists', 'Merge Two Sorted Lists', 'Easy', 'Linked List', 'Merge two ascending linked lists into one ascending list by reusing their nodes. Each input list contains 0 to 50 nodes, and every node value is between -100 and 100.'),
    ('best-time-to-buy-and-sell-stock', 'Best Time to Buy and Sell Stock', 'Easy', 'Array', 'Given daily stock prices, find the maximum profit possible from one purchase followed by one later sale; return 0 if no profit is possible. The array contains 1 to 100,000 positive prices.'),
    ('maximum-subarray', 'Maximum Subarray', 'Medium', 'Dynamic Programming', 'Find the contiguous non-empty subarray with the greatest sum and return that sum. The array contains 1 to 100,000 integers, with each value between -10,000 and 10,000.'),
    ('product-of-array-except-self', 'Product of Array Except Self', 'Medium', 'Array', 'Return an array where each position contains the product of every input value except the value at that position. Do not use division and target linear time; the input has 2 to 100,000 integers and every prefix or suffix product fits in a 32-bit integer.'),
    ('binary-tree-level-order-traversal', 'Binary Tree Level Order Traversal', 'Medium', 'Tree', 'Return the values of a binary tree level by level from left to right. The tree may be empty and contains at most 2,000 nodes, with node values between -1,000 and 1,000.'),
    ('number-of-islands', 'Number of Islands', 'Medium', 'Graph', 'Count the connected groups of land in a rectangular grid of water and land cells, where connections are horizontal or vertical. The grid dimensions are between 1 and 300, and every cell is either 0 or 1.'),
    ('coin-change', 'Coin Change', 'Medium', 'Dynamic Programming', 'Given coin denominations and a target amount, return the fewest coins needed to make that amount, or -1 when it is impossible. There are 1 to 12 distinct positive denominations, and the target amount is between 0 and 10,000.'),
    ('search-in-rotated-sorted-array', 'Search in Rotated Sorted Array', 'Medium', 'Searching', 'Find a target value in a sorted array that has been rotated at an unknown pivot and return its index, or -1 if absent. All values are unique, the array has 1 to 5,000 elements, and the solution should run in logarithmic time.'),
    ('course-schedule', 'Course Schedule', 'Medium', 'Topological Sort', 'Determine whether every course can be completed given prerequisite pairs, which may form a dependency cycle. There are 1 to 2,000 courses and at most 5,000 prerequisite relationships.'),
    ('merge-k-sorted-lists', 'Merge K Sorted Lists', 'Hard', 'Heap', 'Merge an array of ascending linked lists into one ascending linked list. There may be up to 10,000 lists, the total number of nodes is at most 10,000, and node values range from -10,000 to 10,000.'),
    ('trapping-rain-water', 'Trapping Rain Water', 'Hard', 'Two Pointers', 'Given non-negative bar heights of unit width, calculate how much rainwater can be trapped between the bars. The array contains 1 to 20,000 heights, and each height is between 0 and 100,000.'),
    ('n-queens', 'N-Queens', 'Hard', 'Backtracking', 'Place n queens on an n-by-n chessboard so that no two queens attack each other, and return every distinct arrangement. The value of n is between 1 and 9.'),
    ('sort-colors', 'Sort Colors', 'Medium', 'Sorting', 'Sort an array containing only 0, 1, and 2 in place so equal values are adjacent and ordered. The array contains 1 to 300 elements, and a library sort should not be used.'),
    ('jump-game', 'Jump Game', 'Medium', 'Greedy', 'Determine whether the last index can be reached when each array value gives the maximum jump length from that position. The array has 1 to 10,000 non-negative values, each no greater than 100,000.'),
    ('happy-number', 'Happy Number', 'Easy', 'Math', 'Repeatedly replace a positive integer with the sum of the squares of its digits and determine whether the sequence reaches 1. The input is a positive 32-bit integer.'),
    ('single-number', 'Single Number', 'Easy', 'Bit Manipulation', 'Find the only value that appears once in an array where every other value appears exactly twice. The array has 1 to 30,000 integers, and the solution should use linear time and constant extra space.'),
    ('lru-cache', 'LRU Cache', 'Medium', 'Design', 'Design a least-recently-used cache with get and put operations that both run in constant average time. The capacity is between 1 and 3,000, with at most 200,000 operations.'),
    ('second-highest-salary', 'Second Highest Salary', 'Medium', 'Database', 'Write a database query that returns the second-highest distinct employee salary, or null when it does not exist. The employee table has unique IDs and non-negative salary values.'),
    ('tenth-line', 'Tenth Line', 'Easy', 'Shell', 'Write a shell command that prints the tenth line of a text file when that line exists. The input is a valid text file and may contain fewer than ten lines.'),
    ('print-in-order', 'Print in Order', 'Easy', 'Concurrency', 'Coordinate three methods invoked by different threads so they always print first, second, and third in that order. Each method is called exactly once, but thread scheduling is arbitrary.'),
    ('design-url-shortener', 'Design a URL Shortener', 'Hard', 'System Design', 'Design a service that creates short aliases for long URLs and redirects aliases to their original destinations. Consider uniqueness, expiration, high read volume, horizontal scaling, and billions of stored URLs.'),
    ('design-parking-lot', 'Design a Parking Lot', 'Medium', 'Object-Oriented Design', 'Model a parking lot that assigns compatible spaces, tracks tickets, and calculates fees for multiple vehicle types. The design should support multiple floors and allow new pricing or vehicle rules to be added.'),
    ('reverse-linked-list-recursively', 'Reverse a Linked List Recursively', 'Easy', 'Recursion', 'Reverse a singly linked list using recursion and return its new head. The list contains 0 to 5,000 nodes with values between -5,000 and 5,000.'),
    ('group-anagrams', 'Group Anagrams', 'Medium', 'Hash Table', 'Group strings that contain the same letters with the same frequencies, returning the groups in any order. There are 1 to 10,000 lowercase strings, each at most 100 characters long.'),
    ('implement-trie', 'Implement Trie', 'Medium', 'Trie', 'Implement a prefix tree supporting word insertion, exact search, and prefix search. Inputs contain only lowercase English letters, and at most 30,000 operations are performed.'),
    ('range-sum-query-mutable', 'Range Sum Query - Mutable', 'Medium', 'Segment Tree', 'Support point updates and inclusive range-sum queries on an integer array. The array has 1 to 30,000 elements and receives at most 30,000 update or query operations.'),
    ('count-smaller-numbers-after-self', 'Count Smaller Numbers After Self', 'Hard', 'Binary Indexed Tree', 'For each array element, count how many smaller values appear to its right. The array has 1 to 100,000 integers, with values between -10,000 and 10,000.'),
    ('redundant-connection', 'Redundant Connection', 'Medium', 'Union Find', 'Given an undirected graph formed by adding one edge to a tree, return the edge that creates a cycle. The graph has 3 to 1,000 nodes, and each edge connects two distinct nodes.'),
    ('kth-largest-element-in-an-array', 'Kth Largest Element in an Array', 'Medium', 'Divide and Conquer', 'Find the kth-largest value in an unsorted array without fully sorting it. The array contains 1 to 100,000 integers, and k is a valid one-based rank.'),
    ('minimum-size-subarray-sum', 'Minimum Size Subarray Sum', 'Medium', 'Sliding Window', 'Find the shortest contiguous subarray whose sum is at least a target, or return 0 if none exists. The array contains 1 to 100,000 positive integers and the target is positive.'),
    ('number-of-recent-calls', 'Number of Recent Calls', 'Easy', 'Queue', 'Create a counter that reports how many requests occurred within the inclusive 3,000-millisecond window ending at each new request. Request timestamps are strictly increasing, with at most 10,000 calls.'),
    ('design-circular-deque', 'Design Circular Deque', 'Medium', 'Deque', 'Design a fixed-capacity double-ended queue supporting insertion, deletion, and inspection at both ends. Capacity is between 1 and 1,000, with at most 2,000 operations.'),
    ('daily-temperatures', 'Daily Temperatures', 'Medium', 'Monotonic Stack', 'For each daily temperature, return how many days must pass before a warmer temperature occurs, or 0 if none does. There are 1 to 100,000 temperatures between 30 and 100.'),
    ('shortest-subarray-with-sum-at-least-k', 'Shortest Subarray with Sum at Least K', 'Hard', 'Monotonic Queue', 'Find the length of the shortest non-empty subarray with a sum of at least k, or return -1. The array has 1 to 100,000 signed integers, so negative values must be handled.'),
    ('count-square-sum-triples', 'Count Square Sum Triples', 'Easy', 'Brute Force', 'Count ordered triples of positive integers a, b, and c no greater than n where a squared plus b squared equals c squared. The value of n is between 1 and 250.'),
    ('word-break', 'Word Break', 'Medium', 'Memoization', 'Determine whether a string can be split into a sequence of one or more dictionary words, with words reusable. The string has 1 to 300 lowercase characters and the dictionary contains up to 1,000 words.'),
    ('unique-paths', 'Unique Paths', 'Medium', 'Tabulation', 'Count the paths from the top-left to the bottom-right of a grid when movement is limited to right or down. Each grid dimension is between 1 and 100, and the answer fits in a 32-bit integer.'),
    ('nim-game', 'Nim Game', 'Easy', 'Game Theory', 'Determine whether the first player can force a win when two players alternately remove one to three stones from a pile. The pile contains between 1 and 2,147,483,647 stones.'),
    ('random-pick-with-weight', 'Random Pick with Weight', 'Medium', 'Randomized', 'Randomly return an index with probability proportional to its positive integer weight. There are 1 to 10,000 weights, their total fits in a 32-bit integer, and up to 10,000 picks are requested.'),
    ('subsets', 'Subsets', 'Medium', 'Bitmasking', 'Return the power set of an array of unique integers, without duplicate subsets. The array contains at most 10 values, so the result contains exactly 2 raised to the array length subsets.'),
    ('pascals-triangle', 'Pascal''s Triangle', 'Easy', 'Combinatorics', 'Generate the first requested rows of Pascal''s triangle, where each interior value is the sum of the two values above it. The requested row count is between 1 and 30.'),
    ('soup-servings', 'Soup Servings', 'Medium', 'Probability', 'Calculate the probability that soup A becomes empty before soup B, plus half the probability that both empty together, under four equally likely serving choices. The starting amount is between 0 and 1,000,000 milliliters.'),
    ('max-points-on-a-line', 'Max Points on a Line', 'Hard', 'Geometry', 'Find the maximum number of distinct points that lie on the same straight line. There are 1 to 300 points, and each coordinate is between -10,000 and 10,000.'),
    ('network-delay-time', 'Network Delay Time', 'Medium', 'Graph Theory', 'Find how long a signal takes to reach every node in a directed weighted network, or return -1 if any node is unreachable. The graph has 1 to 100 nodes and up to 6,000 positive-weight edges.'),
    ('count-primes', 'Count Primes', 'Medium', 'Number Theory', 'Count the prime numbers strictly less than a non-negative integer n. The value of n is between 0 and 5,000,000.'),
    ('find-first-occurrence-in-a-string', 'Find the First Occurrence in a String', 'Easy', 'String Matching', 'Return the starting index of the first occurrence of a pattern within a text, or -1 when absent. Both strings contain lowercase English letters and have lengths between 1 and 10,000.'),
    ('find-median-from-data-stream', 'Find Median from Data Stream', 'Hard', 'Data Stream', 'Design a structure that accepts integers one at a time and returns the median of all values seen so far. Values range from -100,000 to 100,000, with at most 50,000 total operations.');
